// This file is not generated by Speakeasy. The generated schema table only
// knows the commands generated from the OpenAPI spec; hand-written commands
// register their own entry here so --usage works for them too.

package usage

// RegisterCommand adds the usage schema of a hand-written top-level command:
// the entry `vf <name> --usage` prints, and a copy appended to the root
// schema, so `vf --usage` lists the command beside the generated ones.
// schema is a KDL `cmd` node, as in the generated table.
func RegisterCommand(name, schema string) {
	usageSchemas[name] = schema
	usageSchemas[""] += schema
}
